/**
 * Walton County budgeted staffing and personal services, FY2020 to FY2027.
 * Built from is_primary=Y rows in the Scout payroll extract. Do not edit numbers by hand.
 * Dollars are integer cents. FTE are budgeted positions.
 */

export const STAFF_YEARS = [2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027] as const;
export type StaffYear = (typeof STAFF_YEARS)[number];
export type DollarsBasis = "actual" | "adopted budget";
export type StaffEntityGroup = "bcc" | "sheriff" | "officer" | "courts";

export interface YearTotals {
  fiscalYear: StaffYear;
  fte: number;
  bccFte: number;
  officersFte: number;
  sheriffFte: number;
  restFte: number;
  personalServicesCents: number;
  bccPersonalServicesCents: number;
  officersPersonalServicesCents: number;
  sheriffPersonalServicesCents: number;
  restPersonalServicesCents: number;
  salariesCents: number;
  benefitsCents: number;
  unsplitCents: number;
  dollarsBasis: DollarsBasis;
  dollarsBasisNote: string;
  fteBasisNote: string;
}

export interface DeptYearFigures {
  fte: number | null;
  personalServicesCents: number | null;
  salariesCents: number | null;
  benefitsCents: number | null;
  unsplitCents: number | null;
}

export interface StaffDepartment {
  id: string;
  label: string;
  entity: string;
  entityGroup: StaffEntityGroup;
  transferOnlyDollars: boolean;
  sourceNames: string[];
  byYear: Record<StaffYear, DeptYearFigures>;
}

